   118  /**
   119   * Gets distance from the path in root navigator. In other words how much screen you have to pop to get to the route with this path.
   120   * The search is limited to 5 screens from the top for performance reasons.
   121   * @param path - Path that you are looking for.
   122   * @return - Returns distance to path or -1 if the path is not found in root navigator.
   123   */
   124  function getDistanceFromPathInRootNavigator(path?: string): number {
   125      let currentState = navigationRef.getRootState();
   126
   127      for (let index = 0; index < 5; index++) {
   128          if (!currentState.routes.length) {
   129              break;
   130          }
   131
   132          // When comparing path and pathFromState, the policyID parameter isn't included in the comparison
   133          const currentStateWithoutPolicyID = removePolicyIDParamFromState(currentState as State<RootStackParamList>);
   134          const pathFromState = getPathFromState(currentStateWithoutPolicyID, linkingConfig.config);
   135          if (path === pathFromState.substring(1)) {
   136              return index;
   137          }
   138
   139          currentState = {...currentState, routes: currentState.routes.slice(0, -1), index: currentState.index - 1};
   140      }
   141
   142      return -1;
   143  }
