   210      if (shouldPopToTop) {
   211          if (shouldPopAllStateOnUP) {
   212              shouldPopAllStateOnUP = false;
   213              navigationRef.current?.dispatch(StackActions.popToTop());
   214              return;
   215          }
   216      }
   217
   218      if (!navigationRef.current?.canGoBack()) {
   219          Log.hmmm('[Navigation] Unable to go back');
   220          return;
   221      }
   222
   223      const isFirstRouteInNavigator = !getActiveRouteIndex(navigationRef.current.getState());
   224      if (isFirstRouteInNavigator) {
   225          const rootState = navigationRef.getRootState();
   226          const lastRoute = rootState.routes.at(-1);
   227          // If the user comes from a different flow (there is more than one route in ModalNavigator) we should go back to the previous flow on UP button press instead of using the fallbackRoute.
   228          if ((lastRoute?.name === NAVIGATORS.RIGHT_MODAL_NAVIGATOR || lastRoute?.name === NAVIGATORS.LEFT_MODAL_NAVIGATOR) && (lastRoute.state?.index ?? 0) > 0) {
   229              navigationRef.current.goBack();
   230              return;
   231          }
   232      }
   233
   234      if (shouldEnforceFallback || (isFirstRouteInNavigator && fallbackRoute)) {
   235          navigate(fallbackRoute, CONST.NAVIGATION.TYPE.UP);
   236          return;
   237      }
   238
   239      const isCentralPaneFocused = isCentralPaneName(findFocusedRoute(navigationRef.current.getState())?.name);
   240      const distanceFromPathInRootNavigator = getDistanceFromPathInRootNavigator(fallbackRoute ?? '');
   241
   242      if (isCentralPaneFocused && fallbackRoute) {
   243          // Allow CentralPane to use UP with fallback route if the path is not found in root navigator.
   244          if (distanceFromPathInRootNavigator === -1) {
   245              navigate(fallbackRoute, CONST.NAVIGATION.TYPE.UP);
   246              return;
   247          }
   248
   249          // Add possibility to go back more than one screen in root navigator if that screen is on the stack.
   250          if (distanceFromPathInRootNavigator > 0) {
   251              navigationRef.current.dispatch(StackActions.pop(distanceFromPathInRootNavigator));
   252              return;
   253          }
   254      }
   255
   256      // If the central pane is focused, it's possible that we navigated from other central pane with different matching bottom tab.
   257      if (isCentralPaneFocused) {
   258          const rootState = navigationRef.getRootState();
   259          const stateAfterPop = {routes: rootState.routes.slice(0, -1)} as State<RootStackParamList>;
   260          const topmostCentralPaneRouteAfterPop = getTopmostCentralPaneRoute(stateAfterPop);
   261
   262          const topmostBottomTabRoute = getTopmostBottomTabRoute(rootState as State<RootStackParamList>);
   263          const matchingBottomTabRoute = getMatchingBottomTabRouteForState(stateAfterPop);
   264
   265          // If the central pane is defined after the pop action, we need to check if it's synced with the bottom tab screen.
   266          // If not, we need to pop to the bottom tab screen/screens to sync it with the new central pane.
   267          if (topmostCentralPaneRouteAfterPop && topmostBottomTabRoute?.name !== matchingBottomTabRoute.name) {
